import { z } from 'zod'
import {
  createReminderBodyNagIntervalMinMax,
  createReminderBodyNagIntervalMinMin,
  createReminderBodyNoteMax,
  createReminderBodyTitleMax,
} from '../../lib/api/generated/zod/reminders/reminders'
import type { ChipOption } from '../../components/ui/ChipGroup'
import { fromLocalInputValue, nextAtAsShown, toMinute } from '../../lib/dates'
import { countCharacters } from '../../lib/text'

/**
 * The API's limits, generated by orval from api/swagger.json (so they can't drift apart).
 * "At most a year ahead" is only a description in swagger.json, not a number, so it's kept here
 * (the Go API has the same rule: api/internal/reminders).
 */
export const MAX_TITLE = createReminderBodyTitleMax
export const MAX_NOTE = createReminderBodyNoteMax
export const MIN_NAG_INTERVAL = createReminderBodyNagIntervalMinMin
export const MAX_NAG_INTERVAL = createReminderBodyNagIntervalMinMax
const YEAR_DAYS = 365

/** Inventory → IntervalChips: 15 min to 24 h (values in minutes, as the API wants them). */
export const intervalOptions: ChipOption<string>[] = [
  { value: '15', label: '15 min' },
  { value: '30', label: '30 min' },
  { value: '60', label: '1 h' },
  { value: '120', label: '2 h' },
  { value: '240', label: '4 h' },
  { value: '720', label: '12 h' },
  { value: '1440', label: '24 h' },
]

/** Inventory → UX Copy → "Create form — title placeholder": examples, one at a time. */
export const titleExamples = [
  "Water the plant. It's not dead yet.",
  'Reply to that email from March',
  'Call mum back. For real this time',
  'Return the library book. Yes, that one',
  "Cancel the free trial before it isn't",
]

/** Inventory → TimeChips: quick picks, plus Custom… (the phone's own date-time picker). */
export type WhenChoice = 'in1h' | 'defaultTime' | 'in3h' | 'custom'

export type AddReminderValues = {
  title: string
  note: string
  when: WhenChoice | null
  /** The datetime-local value when `when` is custom, e.g. "2026-10-16T14:30". */
  customAt: string
  interval: string
}

/**
 * The moment a choice means, in the phone's zone. Null if Custom has no valid value yet.
 * `shownNow`: the moment the default-time chip's label was built from, so it saves what it said.
 */
export function resolveDue(
  when: WhenChoice | null,
  customAt: string,
  defaultTimeOfDay: string,
  now: Date = new Date(),
  shownNow: Date = now,
): Date | null {
  switch (when) {
    case 'in1h':
      return toMinute(new Date(now.getTime() + 60 * 60_000))
    case 'in3h':
      return toMinute(new Date(now.getTime() + 3 * 60 * 60_000))
    case 'defaultTime':
      return nextAtAsShown(defaultTimeOfDay, shownNow, now)
    case 'custom':
      return fromLocalInputValue(customAt)
    default:
      return null
  }
}

/** Editing, and the time is still the saved one: nothing to check or send. */
export function keepsSavedTime(
  v: Pick<AddReminderValues, 'when' | 'customAt'>,
  keepCustomAt: string | undefined,
): boolean {
  return keepCustomAt !== undefined && v.when === 'custom' && v.customAt === keepCustomAt
}

/**
 * The form's rules, with the user's copy (Inventory → UX Copy). The time is checked when
 * the form is sent, against the clock at that moment.
 * `keepCustomAt` (editing): the saved time as a datetime-local value. Left as it is, it isn't
 * checked (a nagging reminder's time is already in the past) and isn't sent again.
 */
export function addReminderSchema(defaultTimeOfDay: string, keepCustomAt?: string) {
  return z
    .object({
      title: z
        .string()
        .trim()
        .min(1, { error: 'Title is required' })
        .refine((t) => countCharacters(t) <= MAX_TITLE, {
          error: `Keep the title under ${MAX_TITLE} characters.`,
        }),
      note: z
        .string()
        .trim()
        .refine((t) => countCharacters(t) <= MAX_NOTE, {
          error: `Keep it under ${MAX_NOTE} characters. It's a reminder, not a diary.`,
        }),
      when: z.enum(['in1h', 'defaultTime', 'in3h', 'custom']).nullable(),
      customAt: z.string(),
      interval: z.string().refine((v) => intervalOptions.some((o) => o.value === v), {
        error: 'Pick how often to nag you.',
      }),
    })
    .superRefine((v, ctx) => {
      const now = new Date()
      if (v.when === null) {
        ctx.addIssue({ code: 'custom', path: ['when'], message: 'Pick a time.' })
        return
      }
      if (keepsSavedTime(v, keepCustomAt)) return
      const due = resolveDue(v.when, v.customAt, defaultTimeOfDay, now)
      if (due === null) {
        ctx.addIssue({ code: 'custom', path: ['customAt'], message: 'Pick a date and time.' })
      } else if (due.getTime() < now.getTime() - 60_000) {
        ctx.addIssue({
          code: 'custom',
          path: ['customAt'],
          message: 'That time has already passed.',
        })
      } else if (due.getTime() > now.getTime() + YEAR_DAYS * 86_400_000) {
        ctx.addIssue({
          code: 'custom',
          path: ['customAt'],
          message: "We can't nag that far. We barely know what we're doing next week.",
        })
      }
    })
}
